cd /workspace && python3 - <<'EOF'
import re, glob

# known interfaces: name -> (inputs, outputs), each (pin, width)
iface = {
    'Nand': ({'a':1,'b':1}, {'out':1}),
}
for f in sorted(glob.glob('projects/01/*.hdl')):
    src = open(f).read()
    m = re.search(r'CHIP\s+(\w+)\s*\{(.*?)\}', src, re.S)
    name = m.group(1)
    body = m.group(2)
    inm = re.search(r'IN\s+(.*?);', body, re.S)
    outm = re.search(r'OUT\s+(.*?);', body, re.S)
    def pins(s):
        d = {}
        for p in s.split(','):
            p = p.strip()
            pm = re.match(r'(\w+)(?:\[(\d+)\])?$', p)
            d[pm.group(1)] = int(pm.group(2) or 1)
        return d
    ins, outs = pins(inm.group(1)), pins(outm.group(1))
    iface[name] = (ins, outs)
    parts = body.split('PARTS:')[1]
    conns = {}
    ok = True
    for pm in re.finditer(r'(\w+)\s*\((.*?)\)\s*;', parts, re.S):
        chip = pm.group(1)
        if chip not in iface:
            print(f'{f}: UNKNOWN CHIP {chip}'); ok=False; continue
        cins, couts = iface[chip]
        used_out = set()
        for conn in pm.group(2).split(','):
            cm = re.match(r'\s*(\w+)\s*=\s*(\w+)(?:\[(\d+)(?:\.\.(\d+))?\])?\s*$', conn.strip())
            if not cm:
                print(f'{f}: BAD CONN {conn!r}'); ok=False; continue
            pin, wire, lo, hi = cm.group(1), cm.group(2), cm.group(3), cm.group(4)
            w = (int(hi)-int(lo)+1) if hi else (1 if lo is not None else (cins.get(pin) or couts.get(pin)))
            if pin in cins:
                pw = cins[pin]
            elif pin in couts:
                pw = couts[pin]
                if pin in used_out:
                    print(f'{f}: output pin {pin} of {chip} driven twice'); ok=False
                used_out.add(pin)
            else:
                print(f'{f}: {chip} has no pin {pin}'); ok=False; continue
            if w != pw:
                print(f'{f}: width mismatch {chip}.{pin} ({pw}) vs wire {wire} ({w})'); ok=False
            # check wire exists
            wd = ins.get(wire) or outs.get(wire) or conns.get(wire) or (1 if wire in ('true','false') else None)
            if wd is None:
                print(f'{f}: unknown wire {wire}'); ok=False
            conns.setdefault(wire, w)
    # every output pin must be driven
    driven = set()
    for pm in re.finditer(r'(\w+)\s*\((.*?)\)\s*;', parts, re.S):
        for conn in pm.group(2).split(','):
            cm = re.match(r'\s*(\w+)\s*=\s*(\w+)', conn.strip())
            driven.add(cm.group(2))
    for op in outs:
        if op not in driven and op not in ins:
            print(f'{f}: output {op} never driven'); ok=False
    if ok:
        print(f'{f}: OK')
EOF

cd /workspace && python3 - <<'EOF'
import re, glob

iface = {'Nand': ({'a':1,'b':1}, {'out':1})}
files = sorted(glob.glob('projects/01/*.hdl'))
bodies = {}

def pins(s):
    d = {}
    for p in s.split(','):
        pm = re.match(r'\s*(\w+)(?:\[(\d+)\])?\s*$', p)
        d[pm.group(1)] = int(pm.group(2) or 1)
    return d

# pass 1: interfaces
for f in files:
    src = open(f).read()
    m = re.search(r'CHIP\s+(\w+)\s*\{(.*?)\}', src, re.S)
    name, body = m.group(1), m.group(2)
    ins = pins(re.search(r'IN\s+(.*?);', body, re.S).group(1))
    outs = pins(re.search(r'OUT\s+(.*?);', body, re.S).group(1))
    iface[name] = (ins, outs)
    bodies[f] = (name, body)

# pass 2: validate bodies
allok = True
for f in files:
    name, body = bodies[f]
    ins, outs = iface[name]
    parts = body.split('PARTS:')[1]
    insts = re.findall(r'(\w+)\s*\((.*?)\)\s*;', parts, re.S)
    # collect all wires driven by any part first
    wires = dict(ins); wires.update(outs)
    wires['true'] = 1; wires['false'] = 1
    for chip, conns in insts:
        for conn in conns.split(','):
            cm = re.match(r'\s*(\w+)\s*=\s*(\w+)(?:\[(\d+)(?:\.\.(\d+))?\])?\s*$', conn.strip())
            wires.setdefault(cm.group(2), 0)  # placeholder width, refined below
    ok = True
    driven = set()
    for chip, conns in insts:
        if chip not in iface:
            print(f'{f}: UNKNOWN CHIP {chip}'); ok=False; continue
        cins, couts = iface[chip]
        used_out = set()
        for conn in conns.split(','):
            cm = re.match(r'\s*(\w+)\s*=\s*(\w+)(?:\[(\d+)(?:\.\.(\d+))?\])?\s*$', conn.strip())
            if not cm:
                print(f'{f}: BAD CONN {conn!r}'); ok=False; continue
            pin, wire, lo, hi = cm.groups()
            if pin in cins: pw = cins[pin]
            elif pin in couts:
                pw = couts[pin]
                if pin in used_out:
                    print(f'{f}: {chip}.{pin} driven twice'); ok=False
                used_out.add(pin)
            else:
                print(f'{f}: {chip} has no pin {pin}'); ok=False; continue
            w = (int(hi)-int(lo)+1) if hi else (1 if lo is not None else pw)
            if lo is None and wire in wires and wires[wire] and wires[wire] != pw:
                print(f'{f}: width mismatch {chip}.{pin}({pw}) vs wire {wire}({wires[wire]})'); ok=False
            if lo is None:
                wires[wire] = pw
            if pin in couts:
                driven.add(wire)
    for op in outs:
        if op not in driven:
            print(f'{f}: output {op} never driven'); ok=False
    if ok:
        print(f'{f}: OK')
    else:
        allok = False
print('ALL OK' if allok else 'ERRORS FOUND')
